def _ensure_index(labels, dtype='object'):
    import pandas as pd
    if isinstance(labels[0], str):
        return pd.Index(labels, dtype=dtype)
    else:
        levels = [list(set(sublist)) for sublist in labels]
        labels = [[levels[0].index(item[0]) for item in sublist] for sublist in labels]
        return pd.MultiIndex(levels=levels, labels=labels, dtype=dtype)
